{
  "framework": "wren",
  "question": "2026 年上半年按产品一级分类统计设备订货金额和设备利润。",
  "current_date": "2026-08-04",
  "semantic_context": {
    "source": "actual compiled Wren target/mdl.json plus knowledge/rules",
    "scope_strategy": "full context because the MDL is below Wren's 30,000-character threshold",
    "model": {
      "name": "device_orders",
      "tableReference": {
        "catalog": "demo",
        "schema": "main",
        "table": "device_orders"
      },
      "columns": [
        {
          "name": "order_id",
          "type": "VARCHAR",
          "isPrimaryKey": true
        },
        {
          "name": "order_date",
          "type": "DATE"
        },
        {
          "name": "year_month",
          "type": "INTEGER"
        },
        {
          "name": "org_code",
          "type": "VARCHAR",
          "properties": {
            "description": "组织编码；分析必须显式限定。"
          }
        },
        {
          "name": "product_code",
          "type": "VARCHAR"
        },
        {
          "name": "product_l1",
          "type": "VARCHAR",
          "properties": {
            "description": "产品一级分类。"
          }
        },
        {
          "name": "order_amount",
          "type": "DOUBLE"
        },
        {
          "name": "profit_amount",
          "type": "DOUBLE"
        },
        {
          "name": "country",
          "type": "VARCHAR"
        },
        {
          "name": "status",
          "type": "VARCHAR"
        }
      ],
      "properties": {
        "description": "合成设备订货事实表。每行一张订货单，取消单不得计入指标。"
      }
    },
    "cube": {
      "name": "device_business",
      "baseObject": "device_orders",
      "measures": [
        {
          "name": "device_order_amount",
          "expression": "SUM(CASE WHEN status = 'confirmed' THEN order_amount ELSE 0 END)",
          "type": "DOUBLE"
        },
        {
          "name": "device_profit_amount",
          "expression": "SUM(CASE WHEN status = 'confirmed' THEN profit_amount ELSE 0 END)",
          "type": "DOUBLE"
        }
      ],
      "dimensions": [
        {
          "name": "product_l1",
          "expression": "product_l1",
          "type": "VARCHAR"
        },
        {
          "name": "org_code",
          "expression": "org_code",
          "type": "VARCHAR"
        },
        {
          "name": "year_month",
          "expression": "year_month",
          "type": "INTEGER"
        },
        {
          "name": "status",
          "expression": "status",
          "type": "VARCHAR"
        }
      ],
      "properties": {
        "description": "已确认设备订货金额和利润的可执行 cube。"
      }
    },
    "business_rules": "# 设备业务规则\n\n- `device_order_amount` 只合计 `status = 'confirmed'` 的 `order_amount`。\n- 查询必须显式给出 `org_code`，不得默认跨组织汇总。\n- 演示金额单位为 CNY。\n- “设备订货额”“设备订单金额”都指 `device_order_amount`；“设备利润额”指 `device_profit_amount`。\n- 用户只说“金额”时，无法区分订货金额和利润金额，必须追问。\n- `device_profit_amount` 是设备利润，不是净利润；用户明确询问净利润时不得替代。\n- “销售金额”属于 `sales_orders`，不能代替设备订货金额。\n"
  },
  "required_output": {
    "status": "ready | needs_clarification | unsupported",
    "reason": "简洁说明为什么做出这一判断",
    "clarification_question": "需要追问时填写字符串，否则为 null",
    "query": {
      "cube": "仅允许 device_business",
      "measures": "仅允许 device_order_amount、device_profit_amount",
      "dimensions": "仅允许 product_l1、org_code、year_month、status",
      "filters": [
        "dimension:operator:value；操作符只允许 eq、gte、lte"
      ]
    },
    "query_note": "status 不是 ready 时，query 必须为 null"
  }
}
